import{_ as r,c as a,o as t,a5 as o}from"./chunks/framework.DuCYAsAJ.js";const h=JSON.parse('{"title":"Canal CDC 与 Kafka 消息","description":"","frontmatter":{"title":"Canal CDC 与 Kafka 消息","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#9.3","branch":"main","level":1,"order":9.3,"date":"2026-05-24T00:00:00.000Z"},"headers":[],"relativePath":"posts/projects/zfeed/09-infrastructure-and-deployment/03-canal-cdc-and-kafka-messaging.md","filePath":"posts/projects/zfeed/09-infrastructure-and-deployment/03-canal-cdc-and-kafka-messaging.md","lastUpdated":1779632679000}'),n={name:"posts/projects/zfeed/09-infrastructure-and-deployment/03-canal-cdc-and-kafka-messaging.md"};function c(i,e,l,p,d,s){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="canal-cdc-与-kafka-消息" tabindex="-1">Canal CDC 与 Kafka 消息 <a class="header-anchor" href="#canal-cdc-与-kafka-消息" aria-label="Permalink to &quot;Canal CDC 与 Kafka 消息&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher_test.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/like_strategy.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/like_strategy.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/repositories/count_value_repository.go" target="_blank" rel="noreferrer">app/rpc/count/internal/repositories/count_value_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/interaction.go" target="_blank" rel="noreferrer">app/rpc/interaction/interaction.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_event_outbox_repository.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_event_outbox_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/svc/servicecontext.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/svc/servicecontext.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/conf/canal.properties" target="_blank" rel="noreferrer">deploy/canal/conf/canal.properties</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/conf/count/instance.properties" target="_blank" rel="noreferrer">deploy/canal/conf/count/instance.properties</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/reset-and-start.sh" target="_blank" rel="noreferrer">deploy/canal/reset-and-start.sh</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/mysql/my.cnf" target="_blank" rel="noreferrer">deploy/mysql/my.cnf</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/mysql/mysql-reseed.sh" target="_blank" rel="noreferrer">deploy/mysql/mysql-reseed.sh</a></li></ul></details><p>zfeed 平台使用 Canal 做 Change Data Capture（CDC），以监控 MySQL binlog 并在微服务之间传播状态变更。该架构为高频更新提供最终一致性，例如社交互动计数，同时通过 Kafka 为跨服务事件通知提供可靠机制。</p><h2 id="canal-架构与配置" tabindex="-1">Canal 架构与配置 <a class="header-anchor" href="#canal-架构与配置" aria-label="Permalink to &quot;Canal 架构与配置&quot;">​</a></h2><p>Canal 扮演 MySQL slave，解析 binlog 并将行级变更推送到 Kafka。部署中包含一个专门的 <code>count</code> instance 配置，用于追踪与社交互动相关的表。</p><h3 id="数据流-mysql-到-kafka" tabindex="-1">数据流：MySQL 到 Kafka <a class="header-anchor" href="#数据流-mysql-到-kafka" aria-label="Permalink to &quot;数据流：MySQL 到 Kafka&quot;">​</a></h3><p>流程从 MySQL 中发生写操作开始。Canal 捕获 binlog 事件，并将其转换为结构化 JSON 消息发布到 Kafka topic。</p><p>标题：Canal CDC 流水线</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/conf/count/instance.properties#L1-L20" target="_blank" rel="noreferrer">deploy/canal/conf/count/instance.properties#1-20</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/reset-and-start.sh#L1-L20" target="_blank" rel="noreferrer">deploy/canal/reset-and-start.sh#1-20</a></p><h3 id="关键配置" tabindex="-1">关键配置 <a class="header-anchor" href="#关键配置" aria-label="Permalink to &quot;关键配置&quot;">​</a></h3><ul><li>Binlog Format：MySQL 必须配置为 <code>binlog-format=ROW</code>，以便 Canal 捕获完整行镜像 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/mysql/my.cnf#L1-L10" target="_blank" rel="noreferrer">deploy/mysql/my.cnf#1-10</a></li><li>Canal Instance：<code>count</code> instance 在 <code>instance.properties</code> 中配置，用于过滤 <code>zfeed_like</code>、<code>zfeed_comment</code>、<code>zfeed_favorite</code> 等特定表 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/conf/count/instance.properties#L1-L15" target="_blank" rel="noreferrer">deploy/canal/conf/count/instance.properties#1-15</a></li><li>Reset Logic：<code>reset-and-start.sh</code> 脚本处理过期 PID 清理和可选的元数据重置，以确保 Canal server 干净重启 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/reset-and-start.sh#L6-L16" target="_blank" rel="noreferrer">deploy/canal/reset-and-start.sh#6-16</a></li></ul><h2 id="count-rpc-canal-consumer" tabindex="-1">count-rpc Canal Consumer <a class="header-anchor" href="#count-rpc-canal-consumer" aria-label="Permalink to &quot;count-rpc Canal Consumer&quot;">​</a></h2><p><code>count-rpc</code> 服务从 Kafka 消费 Canal 事件，以更新反规范化计数器。这让系统能够处理高频写入，例如成千上万次点赞，而不会阻塞主要互动事务。</p><h3 id="事件分发与策略" tabindex="-1">事件分发与策略 <a class="header-anchor" href="#事件分发与策略" aria-label="Permalink to &quot;事件分发与策略&quot;">​</a></h3><p><code>count-rpc</code> 中的 <code>Dispatcher</code> 类接收原始 <code>ChangeEvent</code> 对象，并根据表名将其路由到具体的 <code>TableStrategy</code> 实现。</p><p>标题：Count 事件分发</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L22-L44" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#22-44</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/like_strategy.go#L15-L24" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/like_strategy.go#15-24</a></p><h3 id="可靠处理逻辑" tabindex="-1">可靠处理逻辑 <a class="header-anchor" href="#可靠处理逻辑" aria-label="Permalink to &quot;可靠处理逻辑&quot;">​</a></h3><ol><li>幂等性：每个事件都会使用 <code>EventID</code> 检查 <code>zfeed_mq_consume_dedup</code>，避免重复处理 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L66-L74" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#66-74</a></li><li>原子更新：对 <code>zfeed_count_value</code> 表的 delta 更新会在事务中执行，并使用 <code>SELECT ... FOR UPDATE</code> 进行行级锁定 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/repositories/count_value_repository.go#L158-L180" target="_blank" rel="noreferrer">app/rpc/count/internal/repositories/count_value_repository.go#158-180</a></li><li>热门内容评分：每次计数成功更新后，<code>Dispatcher</code> 会计算 <code>heatScoreDelta</code>（例如 Like=1、Comment=3、Favorite=4），并通过 <code>writeHotIncrements</code> 递增 Redis 分片 bucket <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L124-L154" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#124-154</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L163-L177" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#163-177</a></li><li>缓存失效：DB 事务提交后，<code>CountOperator</code> 对 Redis 缓存执行“双删”策略以保证一致性 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go#L84-L108" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go#84-108</a></li></ol><h2 id="transactional-outbox-模式" tabindex="-1">Transactional Outbox 模式 <a class="header-anchor" href="#transactional-outbox-模式" aria-label="Permalink to &quot;Transactional Outbox 模式&quot;">​</a></h2><p><code>interaction-rpc</code> 服务实现 Transactional Outbox 模式，以确保点赞/取消点赞等互动事件能可靠发布到 Kafka，即使 Kafka 集群暂时不可用也不会丢失。</p><h3 id="likeeventoutbox-实现" tabindex="-1">LikeEventOutbox 实现 <a class="header-anchor" href="#likeeventoutbox-实现" aria-label="Permalink to &quot;LikeEventOutbox 实现&quot;">​</a></h3><p>服务不会在 gRPC 请求中直接发布到 Kafka，而是将事件写入 <code>zfeed_like_event_outbox</code> 表，并与互动状态变更放在同一个 MySQL 事务中。</p><p>标题：Transactional Outbox 流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L100-L128" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#100-128</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_event_outbox_repository.go#L63-L85" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_event_outbox_repository.go#63-85</a></p><h3 id="关键组件" tabindex="-1">关键组件 <a class="header-anchor" href="#关键组件" aria-label="Permalink to &quot;关键组件&quot;">​</a></h3><ul><li>LikeProducer：处理初始 <code>enqueueEvent</code>，持久化记录并尝试立即分发 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L70-L98" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#70-98</a></li><li>LikeOutboxRelay：后台 <code>service.Service</code>，会定期轮询 “Due” 事件（其中 <code>status = 10</code> 且 <code>next_retry_at &lt;= now</code>），并尝试重新发布 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L202-L225" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#202-225</a></li><li>Exponential Backoff：如果发布失败，<code>nextLikeEventRetryTime</code> 会根据 <code>retry_count</code> 计算退避时长 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L179-L190" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#179-190</a></li></ul><h3 id="服务集成" tabindex="-1">服务集成 <a class="header-anchor" href="#服务集成" aria-label="Permalink to &quot;服务集成&quot;">​</a></h3><p><code>LikeRelay</code> 在 <code>interaction.go</code> 中注册到 <code>ServiceGroup</code>，确保它和 RPC server 一起运行 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/interaction.go#L46-L59" target="_blank" rel="noreferrer">app/rpc/interaction/interaction.go#46-59</a>。<code>ServiceContext</code> 使用 <code>kq.Pusher</code> 和 GORM 数据库句柄初始化 producer <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/svc/servicecontext.go#L29-L54" target="_blank" rel="noreferrer">app/rpc/interaction/internal/svc/servicecontext.go#29-54</a></p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/interaction.go#L46-L59" target="_blank" rel="noreferrer">app/rpc/interaction/interaction.go#46-59</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/svc/servicecontext.go#L29-L54" target="_blank" rel="noreferrer">app/rpc/interaction/internal/svc/servicecontext.go#29-54</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L37-L46" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#37-46</a></p>',30)])])}const u=r(n,[["render",c]]);export{h as __pageData,u as default};
